import{_ as l,o as i,c as e,a2 as n}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"控制面与自主性","description":"Hearth Control Plane 的 Trigger、Policy、Mandate、调度、Watchdog、注意力预算与主动循环。","frontmatter":{"title":"控制面与自主性","description":"Hearth Control Plane 的 Trigger、Policy、Mandate、调度、Watchdog、注意力预算与主动循环。","outline":[2,3]},"headers":[],"relativePath":"architecture/control-plane.md","filePath":"architecture/control-plane.md","lastUpdated":1793706118000}'),t={name:"architecture/control-plane.md"};function s(o,a,r,p,c,d){return i(),e("div",null,[...a[0]||(a[0]=[n(`<p class="eyebrow">CONTROL PLANE</p><h1 id="控制面与自主性" tabindex="-1">控制面与自主性 <a class="header-anchor" href="#控制面与自主性" aria-label="Permalink to &quot;控制面与自主性&quot;">​</a></h1><p class="lead">谁决定做什么、是否允许、何时打扰、何时暂停。控制面不是执行器，而是任务与授权的判断层。</p><h2 id="control-plane-与自主性" tabindex="-1">Control Plane 与自主性 <a class="header-anchor" href="#control-plane-与自主性" aria-label="Permalink to &quot;Control Plane 与自主性&quot;">​</a></h2><p>Control Plane 决定：</p><ul><li>事件是否值得处理；</li><li>是否创建 Task；</li><li>是否需要用户审批；</li><li>应用哪个 Executor；</li><li>花多少 Token、时间和金钱；</li><li>何时通知、何时静默；</li><li>失败后重试、换路还是转人工。</li></ul><p>它不直接调用工具，不直接持有凭据，也不直接写外部服务。</p><h3 id="trigger" tabindex="-1">Trigger <a class="header-anchor" href="#trigger" aria-label="Permalink to &quot;Trigger&quot;">​</a></h3><p>Trigger 是规则、订阅和条件的组合：cron、文件变化、网页变化、邮件到达、日历临近、GitHub Issue/PR、设备上线/离线、任务依赖完成、用户显式订阅和失败重试。</p><p>规则命中的可以直接创建 Ticket；只有需要语义判断时才调用小模型。Trigger 不是“让大模型一直观察一切”。</p><h3 id="policy-与-mandate" tabindex="-1">Policy 与 Mandate <a class="header-anchor" href="#policy-与-mandate" aria-label="Permalink to &quot;Policy 与 Mandate&quot;">​</a></h3><p>Policy 是长期规则，Mandate 是一次或一段时间的授权实例。</p><p>Mandate 至少包含：</p><ul><li>允许的动作类型；</li><li>资源范围；</li><li>联系人/域名/仓库/文件夹范围；</li><li>风险等级；</li><li>预算；</li><li>有效期；</li><li>是否允许自动执行；</li><li>是否允许转发或委托；</li><li>撤销方式。</li></ul><p>模型可以提出建议，但不能修改 Mandate、Approval 或自身 capability。</p><h3 id="调度与-watchdog" tabindex="-1">调度与 Watchdog <a class="header-anchor" href="#调度与-watchdog" aria-label="Permalink to &quot;调度与 Watchdog&quot;">​</a></h3><p>调度器负责优先级、并发上限、设备/Executor 匹配、预算、截止时间、依赖等待和公平性。</p><p>Watchdog 独立于 Agent 运行，负责：</p><ul><li>卡死检测；</li><li>死循环检测；</li><li>预算超支；</li><li>设备失联；</li><li>凭据失效；</li><li>外部平台异常；</li><li>自动降级或转人工。</li></ul><p>Watchdog 不是另一个模型，而是一组确定性监督机制。</p><h3 id="自主性的正确边界" tabindex="-1">自主性的正确边界 <a class="header-anchor" href="#自主性的正确边界" aria-label="Permalink to &quot;自主性的正确边界&quot;">​</a></h3><p>自主性不是“模型想做什么就做什么”，而是：</p><ul><li>在明确 Mandate 内自主；</li><li>在预算内自主；</li><li>在可恢复/可回滚范围内自主；</li><li>在低风险场景中自主；</li><li>高风险动作始终保留人类确认。</li></ul><h3 id="注意力预算" tabindex="-1">注意力预算 <a class="header-anchor" href="#注意力预算" aria-label="Permalink to &quot;注意力预算&quot;">​</a></h3><p>每个任务都有注意力预算，而不只是 Token 预算：</p><ul><li>最多打断次数；</li><li>聚合窗口；</li><li>静默时段；</li><li>默认动作；</li><li>升级条件；</li><li>用户关闭渠道后的行为。</li></ul><p>规则：</p><ul><li>能自动验证的不要求人确认；</li><li>能安全等待的不即时打扰；</li><li>能批量审批的不逐条打断；</li><li>每次打断必须有一个明确动作；</li><li>同一任务打断超过 2 次且无法下降，退回“只建议不执行”。</li></ul><h3 id="主动循环" tabindex="-1">主动循环 <a class="header-anchor" href="#主动循环" aria-label="Permalink to &quot;主动循环&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Source Event</span></span>
<span class="line"><span>  → Trigger / Rule</span></span>
<span class="line"><span>  → Small classifier</span></span>
<span class="line"><span>  → Task / Thread</span></span>
<span class="line"><span>  → Policy + Mandate</span></span>
<span class="line"><span>  → Budget</span></span>
<span class="line"><span>  → Executor</span></span>
<span class="line"><span>  → Verification</span></span>
<span class="line"><span>  → Notification / Receipt</span></span></code></pre></div><p>主动模式与建议模式必须可独立开关，并且有对照数据。第四阶段之前不开放真实主动循环。</p>`,31)])])}const g=l(t,[["render",s]]);export{u as __pageData,g as default};
